#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

/**
 * Problem: 2015-09 - Longest Increasing Subsequence
 * 
 * 解題思路：
 * 1. 尋找最長遞增子序列 (LIS) 的長度。
 * 2. 題目給出的 n 最大為 65535，O(n^2) 的動態規劃在 15 秒內可能通過，但最優解是 O(n log n)。
 * 3. 使用「尾端陣列」(tail array) 維護：
 *    - tails[i] 表示長度為 i+1 的遞增子序列中，最小的末尾元素。
 *    - 遍歷原陣列，對於每個元素 x：
 *        - 如果 x 比 tails 的所有元素都大，則將 x 加入 tails 末尾（LIS 長度增加）。
 *        - 否則，在 tails 中找到第一個大於等於 x 的元素並替換它（保持末尾元素最小）。
 * 4. 最後 tails 的長度即為 LIS 的長度。
 */

int main() {
    int n;
    while (cin >> n) {
        vector<int> nums(n);
        for (int i = 0; i < n; i++) cin >> nums[i];

        if (n == 0) {
            cout << 0 << endl;
            continue;
        }

        vector<int> tails;
        for (int x : nums) {
            auto it = lower_bound(tails.begin(), tails.end(), x);
            if (it == tails.end()) {
                tails.push_back(x);
            } else {
                *it = x;
            }
        }
        cout << tails.size() << endl;
    }
    return 0;
}
